BACKUPS = []


def normalize_newlines(text: str) -> str:
    return text.replace("\r\n", "\n").replace("\r", "\n")


def read_text_with_newline(path: Path) -> tuple[str, str]:
    raw = path.read_bytes()
    newline = "\r\n" if b"\r\n" in raw else "\n"

    try:
        text = raw.decode("utf-8")
    except UnicodeDecodeError as error:
        fail(f"Unable to decode {path}: {error}")

    return normalize_newlines(text), newline


def write_text_with_newline(path: Path, text: str, newline: str) -> None:
    normalized = normalize_newlines(text)
    rendered = normalized if newline == "\n" else normalized.replace("\n", "\r\n")
    path.write_bytes(rendered.encode("utf-8"))


def backup(path: Path) -> None:
    backup_path = path.with_name(
        f"{path.name}.backup-phase-3d-fe1-{STAMP}"
    )
    shutil.copy2(path, backup_path)
    BACKUPS.append((path, backup_path))
    print(f"Backup: {backup_path}")


def rollback() -> None:
    if not BACKUPS:
        return

    print("\nRestoring backups...")

    for original, backup_path in reversed(BACKUPS):
        if backup_path.exists():
            shutil.copy2(backup_path, original)
            print(f"Restored: {original}")


def fail(message: str) -> None:
    print(f"\nERROR: {message}", file=sys.stderr)
    rollback()
    raise SystemExit(1)


def apply_hunks(path: Path, hunks) -> None:
    text, newline = read_text_with_newline(path)

    for position, old, new in sorted(
        hunks,
        key=lambda item: item[0],
        reverse=True
    ):
        count = text.count(old)

        if count != 1:
            fail(
                f"{path} near source line {position + 1}: "
                f"expected exactly one audited match, found {count}. "
                "Use the exact latest files uploaded for Phase 3D-FE-1."
            )

        text = text.replace(old, new, 1)

    write_text_with_newline(path, text, newline)


required_paths = [ROOT / relative for relative in PATCHES]

for path in required_paths:
    if not path.exists():
        fail(f"Missing required file: {path}")

for path in required_paths:
    backup(path)

for relative, hunks in PATCHES.items():
    apply_hunks(ROOT / relative, hunks)

syntax_targets = [
    ROOT / "public/js/dashboard.js",
    ROOT / "public/js/plaza.js",
    ROOT / "public/js/yhu-game-dashboard.js"
]

for target in syntax_targets:
    result = subprocess.run(
        ["node", "--check", str(target)],
        cwd=ROOT,
        capture_output=True,
        text=True
    )

    if result.returncode != 0:
        print(result.stdout)
        print(result.stderr, file=sys.stderr)
        fail(f"JavaScript syntax check failed: {target}")

